// ─── File: YoungGenDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.younggen;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class YoungGenDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        long minorBefore = minorGcCount();

        // LONG-LIVED object: survives many Minor GCs → ages → tenured to Old gen.
        RateCache cache = new RateCache();
        cache.put("USD", new BigDecimal("83.25"));

        // SHORT-LIVED objects: born in Eden, die almost immediately,
        // driving frequent Minor GCs (copying collection).
        BigDecimal totalFees = BigDecimal.ZERO;
        for (int i = 0; i < 2_000_000; i++) {
            TransferRequest req = new TransferRequest("SAV2001", "CUR3001",
                    new BigDecimal("1000"), cache.get("USD"));
            totalFees = totalFees.add(req.computeFee()); // req becomes garbage after this
        }

        long minorAfter = minorGcCount();
        BigDecimal fees = totalFees;
        log.info(() -> "processed 2,000,000 short-lived TransferRequests");
        log.info(() -> "Minor GCs during run = " + (minorAfter - minorBefore)
                + " (Eden filled repeatedly, survivors copied Eden→Survivor)");
        log.info(() -> "long-lived RateCache survived all Minor GCs → tenured to Old gen");
        log.info(() -> "accumulated fees = Rs." + fees);
    }

    // Sum collection counts of the young-generation collectors.
    private static long minorGcCount() {
        long total = 0;
        for (java.lang.management.GarbageCollectorMXBean gc :
                java.lang.management.ManagementFactory.getGarbageCollectorMXBeans()) {
            String n = gc.getName();
            if (n.contains("Young") || n.contains("Scavenge") || n.contains("G1 Young")
                    || n.contains("Copy") || n.contains("ParNew")) {
                total += gc.getCollectionCount();
            }
        }
        return total;
    }
}

// ─── Would be in RateCache.java (LONG-LIVED, gets tenured) ───
class RateCache {
    private final java.util.Map<String, BigDecimal> rates = new java.util.HashMap<>();
    void put(String ccy, BigDecimal rate) { rates.put(ccy, rate); }
    BigDecimal get(String ccy) { return rates.get(ccy); }
}

// ─── Would be in TransferRequest.java (SHORT-LIVED, dies in Young gen) ───
class TransferRequest {
    private final String from;
    private final String to;
    private final BigDecimal amount;
    private final BigDecimal rate;
    TransferRequest(String from, String to, BigDecimal amount, BigDecimal rate) {
            this.from = from;
            this.to = to
            this.amount = amount
            this.rate = rate;
    }
    BigDecimal computeFee() { return amount.multiply(new BigDecimal("0.001")); }
}
